<script setup lang="ts">import { computed,onMounted,ref } from 'vue'; import PageHeader from '../components/PageHeader.vue'; import MetricCard from '../components/MetricCard.vue'; import RuntimeBanner from '../components/RuntimeBanner.vue'; import CommandFeedback from '../components/CommandFeedback.vue'; import { useProjectStore } from '../stores/projectStore'; const store=useProjectStore(); const p=computed(()=>store.project), x=computed(()=>store.production); const last=ref('none'); const state=computed(()=>store.commandState(last.value)); onMounted(()=>void store.loadProduction()); async function cmd(key:string,type:'production_start'|'production_pause'|'production_resume'|'production_cancel'){last.value=key; await store.runCommand(key,{type})}</script>
<template><div v-if="p && x" class="page"><PageHeader title="AI 制片中心" subtitle="展示可恢复的生产进度；页面事件不是权威事实，操作完成后重新查询正式投影。"><button v-if="p.runState==='ACTIVE'" class="btn" @click="cmd('pause','production_pause')">暂停</button><button v-if="p.runState==='PAUSED'" class="btn primary" @click="cmd('resume','production_resume')">恢复</button></PageHeader><RuntimeBanner :state="p.runState" :reason="p.blockReason"/><CommandFeedback :state="state"/><div class="metric-grid section"><MetricCard label="当前工作" :value="x.activeWork.label" :note="x.activeWork.detail"/><MetricCard label="正式章节" :value="p.committedChapters" note="候选稿不会进入成品计数"/><MetricCard label="项目成本" :value="`¥${x.costSummary.projectTotal.toFixed(2)}`" :note="`剩余预算 ¥${x.costSummary.budgetRemaining.toFixed(2)}`"/><MetricCard label="开篇评估" :value="x.signing.status==='PASS'?'通过':x.signing.status==='REVISE'?'需修订':'进行中/未开始'" :note="x.signing.verdict"/></div><div class="production-layout section"><section class="card pad"><div class="card-head"><div><h2 class="card-title">生产时间线</h2><p class="card-subtitle">长任务按书 / 卷 / 章局部恢复。</p></div></div><div class="timeline"><div v-for="t in x.timeline" :key="t.id" class="timeline-item" :class="t.status"><div class="timeline-marker">{{ t.status==='done'?'✓':t.order }}</div><div><strong>{{ t.title }}</strong><div class="muted" style="font-size:12px">{{ t.description }}</div></div></div></div></section><aside style="display:grid;gap:16px"><section class="card pad"><h2 class="card-title">当前任务</h2><div class="task-list"><div v-for="t in x.tasks" :key="t.id" class="task-row"><strong>{{ t.title }}</strong><div class="muted" style="font-size:11px">{{ t.description }}</div><div v-if="t.progress" class="progress" style="margin-top:8px"><span :style="{width:`${t.progress}%`}"/></div></div></div></section><section class="card pad"><h2 class="card-title">最近产物</h2><div class="artifact-list"><div v-for="a in x.artifacts.items" :key="a.id" class="artifact-row"><div><strong>{{ a.title }}</strong><small class="muted">{{ a.summary }}</small></div><span class="badge" :class="a.status==='official'?'success':'warning'">{{ a.status==='official'?'已确认':'制作中' }}</span></div></div></section></aside></div></div></template>
